using System;
using System.IO;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using Object=UnityEngine.Object;
namespace CoastalFactory.Editor {public static partial class LeftFactoryDistrictBuilder {
[Serializable]public class RoadTri {public int channel; public float[] xy;}
[Serializable]public class RoadBox {public float[] xy;}
[Serializable]public class RoadExport {public List<RoadTri> triangles=new List<RoadTri>();public List<Vector2> junctions=new List<Vector2>();public List<RoadBox> buildings=new List<RoadBox>();}
[Serializable]public class RoadResult {public RoadLayer[] layers;public string report;}
[Serializable]public class RoadLayer {public int channel;public float[] xy;}
static readonly string[] UnifiedRoadSources={"GroundRoadNetwork","FactoryRoads_RetainedToRearBoundary"};
[MenuItem("Anseong/Art/Export Road Geometry")]
public static void ExportRoadGeometry(){EditorSceneManager.OpenScene(Scene);var data=new RoadExport();foreach(var name in UnifiedRoadSources){var g=GameObject.Find(name);if(!g)throw new Exception("Missing road "+name);var mesh=g.GetComponent<MeshFilter>().sharedMesh;var v=mesh.vertices;var mats=g.GetComponent<MeshRenderer>().sharedMaterials;for(int sub=0;sub<mesh.subMeshCount;sub++){string mat=mats[sub].name;int ch=mat.Contains("Asphalt")?0:mat.Contains("White")?1:mat.Contains("Yellow")?2:-1;if(ch<0)continue;var indices=mesh.GetTriangles(sub);for(int i=0;i<indices.Length;i+=3){var t=new RoadTri{channel=ch,xy=new float[6]};for(int k=0;k<3;k++){var p=g.transform.TransformPoint(v[indices[i+k]]);t.xy[k*2]=p.x;t.xy[k*2+1]=p.z;}data.triangles.Add(t);}}}foreach(var t in Object.FindObjectsByType<Transform>(FindObjectsSortMode.None)){if(!PrefabUtility.IsOutermostPrefabInstanceRoot(t.gameObject))continue;string path=PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(t.gameObject);if(!(path.Contains("IndustrialBuildings/")||path.Contains("Warehouse/")||path.Contains("UtilityPlant/")||path.Contains("StorageSilo/")))continue;var b=B(t.gameObject);data.buildings.Add(new RoadBox{xy=new[]{b.min.x,b.min.z,b.max.x,b.max.z}});}
// Cross-site junctions and branch entries from the approved road layout.
foreach(float z in new[]{610f,970f}){data.junctions.Add(new Vector2(-760,z));data.junctions.Add(new Vector2(125,z+60));}foreach(float z in new[]{-200f,100f,360f}){data.junctions.Add(new Vector2(-570,z));data.junctions.Add(new Vector2(-490,z+15));}foreach(var p in new[]{new Vector2(-330,530),new Vector2(-250,690),new Vector2(-245,1030),new Vector2(-160,280),new Vector2(160,280),new Vector2(-160,-280),new Vector2(160,-280)})data.junctions.Add(p);Directory.CreateDirectory("Tools/RoadCleanup");File.WriteAllText("Tools/RoadCleanup/road_union_input.json",JsonUtility.ToJson(data));Debug.Log("ROAD_EXPORT_PASS triangles="+data.triangles.Count);}
[MenuItem("Anseong/Art/Apply Unified Smooth Roads")]
public static void ApplyUnifiedSmoothRoads(){EditorSceneManager.OpenScene(Scene);const string folder="Assets/_Anseong/Art/Environment/UnifiedSmoothRoads";Folder(folder);if(GameObject.Find("Roads_UnifiedSmoothSurface"))throw new Exception("Already applied");var result=JsonUtility.FromJson<RoadResult>(File.ReadAllText("Tools/RoadCleanup/road_union_result.json"));var mesh=new Mesh{name="UnifiedSmoothRoadSurface",indexFormat=UnityEngine.Rendering.IndexFormat.UInt32};var vertices=new List<Vector3>();var indices=new List<int>[3];for(int c=0;c<3;c++)indices[c]=new List<int>();foreach(var layer in result.layers){for(int i=0;i<layer.xy.Length;i+=6){int start=vertices.Count;float y=layer.channel==0?.038f:layer.channel==1?.052f:.054f;for(int k=0;k<3;k++)vertices.Add(new Vector3(layer.xy[i+k*2],y,layer.xy[i+k*2+1]));indices[layer.channel].AddRange(new[]{start,start+2,start+1});}}mesh.SetVertices(vertices);mesh.subMeshCount=3;for(int c=0;c<3;c++)mesh.SetTriangles(indices[c],c);mesh.RecalculateNormals();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,folder+"/UnifiedRoadSurface.asset");var g=new GameObject("Roads_UnifiedSmoothSurface");g.AddComponent<MeshFilter>().sharedMesh=mesh;g.AddComponent<MeshRenderer>().sharedMaterials=new[]{AssetDatabase.LoadAssetAtPath<Material>("Assets/_Anseong/Art/Environment/GroundRoadsV2/Asphalt.mat"),AssetDatabase.LoadAssetAtPath<Material>("Assets/_Anseong/Art/Environment/GroundRoadsV2/RoadWhite.mat"),AssetDatabase.LoadAssetAtPath<Material>("Assets/_Anseong/Art/Environment/GroundRoadsV2/CentreYellow.mat")};foreach(var name in UnifiedRoadSources)GameObject.Find(name).SetActive(false);File.WriteAllText(folder+"/VerificationReport.md",result.report);AssetDatabase.Refresh();AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),Scene);Capture(Camera.main,"SmoothRoads_Main");var go=new GameObject("RoadJunctionPreview");var cam=go.AddComponent<Camera>();cam.CopyFrom(Camera.main);cam.transform.position=new Vector3(-280,190,370);cam.transform.LookAt(new Vector3(-320,0,530));Capture(cam,"SmoothRoads_Junction");cam.transform.position=new Vector3(-350,300,750);cam.transform.LookAt(new Vector3(-400,0,650));Capture(cam,"SmoothRoads_Factory");Object.DestroyImmediate(go);Debug.Log("UNIFIED_ROADS_PASS vertices="+vertices.Count+" buildingsAndVehiclesUnchanged=true");}
}}